#include <WiFi.h>
#include <HTTPClient.h>

#define TRIGGER_BUTTON_PIN 14
#define STATUS_LED_PIN     27

const char* MUSE_AGENT_ENDPOINT = "https://api.muse.meta.internal/v1/agent/dispatch";

void loop() {
  if (digitalRead(TRIGGER_BUTTON_PIN) == LOW) {
    digitalWrite(STATUS_LED_PIN, HIGH); // 点亮实体呼吸灯
    HTTPClient http;
    http.begin(MUSE_AGENT_ENDPOINT);
    http.addHeader("Content-Type", "application/json");
    int code = http.POST("{\"action\": \"INBOX_TRIAGE_AND_SUMMARY\"}");
    Serial.printf("Muse Agent Dispatched! Response: %d\n", code);
    http.end();
    delay(1200);
  }
}
